const items = [
  { id: 1, price: 8 },
  { id: 2, price: 25 },
  { id: 3, price: 12 },
];

const grouped = Object.groupBy(items, (x) => (x.price >= 10 ? "high" : "low"));
grouped.low[0].price = 99;

console.log(grouped.high.length, grouped.low.length);
console.log(items[0].price);
console.log(Object.getPrototypeOf(grouped), Object.hasOwn(grouped, "high"));
